"""Website and popup templates. Shared controls, distinct layouts."""
import html

NAMES={'auto':'Auto','tr':'Türkçe','en':'English','de':'Deutsch','es':'Español','fr':'Français','pt':'Português'}
PATHS={
'scan':'M4 9V5a1 1 0 0 1 1-1h4m6 0h4a1 1 0 0 1 1 1v4m0 6v4a1 1 0 0 1-1 1h-4m-6 0H5a1 1 0 0 1-1-1v-4M3 12h18',
'qr':'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h2v2h-2zM18 14h2v4h-2zM14 18h2v2h-2zM18 20h2',
'globe':'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z',
'sun':'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',
'moon':'M20.5 13A8.5 8.5 0 0 1 11 3.5a8.5 8.5 0 1 0 9.5 9.5Z',
'system':'M3 4h18v13H3zM8 21h8m-4-4v4',
'arrow':'M7 17 17 7M7 7h10v10',
'download':'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',
'copy':'M9 9h12v12H9zM15 5V3H3v12h2',
'shield':'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3ZM8 12l3 3 5-6',
'link':'m10 14 4-4m-6 7-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2-1 1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',
'text':'M4 5h16M12 5v15M8 20h8',
'wifi':'M3 8a14 14 0 0 1 18 0M6 12a9 9 0 0 1 12 0m-9 4a4 4 0 0 1 6 0m-3 4h.01',
'email':'M3 5h18v14H3zM3 6l9 7 9-7',
'phone':'M6 3H3c-1 10 8 19 18 18v-3l-5-3-3 3-7-7 3-3-3-5Z',
'sms':'M3 3h18v15H9l-6 4V3ZM7 8h10M7 12h6',
'vcard':'M3 4h18v16H3zM14 9h4m-4 4h4M7 8h3v3H7zM6 16v-2h5v2',
'upload':'M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6',
'camera':'M8 5l2-2h4l2 2h5v15H3V5h5ZM12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',
'check':'m5 12 4 4L19 6',
'chevron':'m8 10 4 4 4-4',
'close':'m6 6 12 12M6 18 18 6',
'folder':'M3 6h7l2 3h9v12H3V6Z',
'code':'m8 7-5 5 5 5m8-10 5 5-5 5m-3-14-2 18',
}
def icon(name,cls=''):
 return f'<svg class="icon {cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{PATHS.get(name,PATHS["qr"])}"/></svg>'
def t(k):return '<span data-i18n="'+k+'">{{'+k+'}}</span>'
def a(k,href,cls='',extra=''):
 return f'<a class="{cls}" href="{href}" {extra}>{t(k)}</a>'
def prefs():
 languages=''.join(f'<button type="button" data-language="{code}" role="menuitemradio" aria-checked="false"><span>{name if code!="auto" else t("autoLanguage")}</span><span class="menu-check">{icon("check")}</span></button>' for code,name in NAMES.items())
 themes=''.join(f'<button type="button" data-theme-choice="{code}" role="menuitemradio" aria-checked="false">{icon(glyph)}{t(code)}<span class="menu-check">{icon("check")}</span></button>' for code,glyph in [('auto','system'),('light','sun'),('dark','moon')])
 return f'<div class="preferences"><details class="pref-menu" id="language-menu"><summary aria-label="Language">{icon("globe")}<span id="language-label">TR</span>{icon("chevron","chevron")}</summary><div class="pref-options" role="menu">{languages}</div></details><details class="pref-menu" id="theme-menu"><summary aria-label="Theme"><span id="theme-icon">{icon("system")}</span><span class="sr-only">{t("theme")}</span>{icon("chevron","chevron")}</summary><div class="pref-options theme-options" role="menu">{themes}</div></details></div>'
def header():
 return f'<a href="#main" class="skip">{t("skip")}</a><header class="site-header"><div class="container nav"><a class="brand" href="./"><img src="/assets/brand/logo.svg" width="38" height="38" alt=""><span>QR Scanner<small>by HaKING</small></span></a><nav aria-label="Main">{a("tools","./#toolkit")}{a("navExtension","./#extension")}{a("install","help.html")}{a("navAbout","about.html")}</nav>{prefs()}</div></header>'
def footer(v):
 return f'<footer class="site-footer"><div class="container footer-top"><div><a class="brand" href="./"><img src="/assets/brand/logo.svg" width="32" height="32" alt=""><span>QR Scanner</span></a><p>{t("footerTag")}</p><small>© 2026 HaKING · v{v}</small></div><div class="footer-links">{a("navAbout","about.html")}{a("privacy","privacy.html")}{a("install","help.html")}{a("source","https://github.com/HaKING06/QR")}</div><div class="footer-contact">{t("contact")}<a href="mailto:qr@haking.tr">qr@haking.tr {icon("arrow")}</a></div></div><div class="container footer-bottom">{icon("shield")}{t("formatHint")}<a href="https://haking.tr/">HaKING ↗</a></div></footer>'
def field(id,key,kind='text',extra=''):
 return f'<label for="{id}">{t(key)}</label><input id="{id}" type="{kind}" {extra}>'
def tool(v,popup=False):
 types=[('url','url','link'),('text','text','text'),('wifi','wifi','wifi'),('email','email','email'),('phone','phone','phone'),('sms','sms','sms'),('vcard','vcard','vcard')]
 select='<select id="type" aria-label="QR type"'+('' if popup else ' class="sr-only" tabindex="-1"')+'>'+''.join(f'<option value="{value}" data-i18n="{key}">{{{{{key}}}}}</option>' for value,key,_ in types)+'</select>'
 pills='' if popup else '<div class="type-picker" role="group" aria-label="QR type">'+''.join(f'<button type="button" data-qr-type="{value}" aria-pressed="{str(value=="url").lower()}">{icon(glyph)}{t(key)}</button>' for value,key,glyph in types)+'</div>'
 return f'''<section class="tool" id="toolkit"><div class="workspace-bar"><div class="tool-tabs" role="tablist"><button id="create-tab" role="tab" aria-controls="create-panel" aria-selected="{str(not popup).lower()}">{icon('qr')}{t('navCreate')}</button><button id="read-tab" role="tab" aria-controls="read-panel" aria-selected="{str(popup).lower()}">{icon('scan')}{t('navRead')}</button></div><span class="local-tag">{icon('shield')}{t('local')}</span></div>
 <div id="create-panel" role="tabpanel" aria-labelledby="create-tab" {'hidden' if popup else ''}><div class="tool-grid"><form id="generator" novalidate><div class="form-intro"><h2>{t('toolTitle')}</h2><p>{t('contentHint')}</p></div>{select}{pills}
 <label for="content" id="content-label">{t('content')}</label><textarea id="content" rows="2" maxlength="2200" placeholder="https://example.com" spellcheck="false"></textarea>
 <div id="wifi-fields" hidden>{field('password','password','password','maxlength="128" autocomplete="off"')}<div class="field-row"><div><label for="security">{t('security')}</label><select id="security"><option value="WPA">WPA / WPA2 / WPA3</option><option value="WEP">WEP</option><option value="nopass" data-i18n="noPassword">Open network</option></select></div><label class="checkbox-label" for="hidden-network"><input type="checkbox" id="hidden-network">{t('hiddenNetwork')}</label></div></div>
 <div id="email-fields" hidden>{field('subject','subject','text','maxlength="200"')}</div><div id="sms-fields" hidden><label for="message">{t('message')}</label><textarea id="message" rows="2" maxlength="1000"></textarea></div>
 <div id="vcard-fields" hidden>{field('organization','organization','text','maxlength="100"')}{field('contact-phone','phone','tel','maxlength="50"')}{field('contact-email','email','email','maxlength="150"')}</div>
 <details class="customize" {'open' if not popup else ''}><summary>{icon('qr')}{t('customize')}{icon('chevron','chevron')}</summary><div class="customize-body"><div class="field-row"><div><label for="size">{t('size')}</label><select id="size"><option>512</option><option selected>1024</option><option>2048</option></select></div><div><label for="color">{t('color')}</label><select id="color"><option value="#11162b">Graphite</option><option value="#3048d8">Cobalt</option><option value="#7027a0">Violet</option></select></div></div><label for="correction">{t('correction')}</label><select id="correction"><option value="M">M · 15%</option><option value="Q">Q · 25%</option><option value="H">H · 30%</option></select></div></details>
 <p id="form-message" class="form-message" role="status" aria-live="polite"></p><button class="button primary wide" type="submit">{t('generate')}{icon('arrow')}</button></form>
 <div class="preview"><div class="preview-top"><span class="eyebrow">{t('automaticPreview')}</span><span class="format-chip">PNG / SVG</span></div><div class="qr-paper" id="qr-preview" role="img" aria-label="QR preview"><div class="empty-qr">{icon('qr')}<span>{t('preview')}</span></div></div><p class="preview-caption" id="preview-caption">{t('sample')}</p><div class="exports"><button class="button primary" id="png" disabled>{icon('download')}{t('png')}</button><button class="button secondary" id="svg" disabled>{icon('download')}SVG</button></div><div class="preview-extras"><button type="button" class="text-button" id="copy-image" disabled>{icon('copy')}{t('copyImage')}</button><button class="text-button" id="clear" type="button">{t('clear')}</button></div><small class="muted">{icon('shield')}{t('formatHint')}</small></div></div></div>
 <div id="read-panel" role="tabpanel" aria-labelledby="read-tab" {'' if popup else 'hidden'}><div class="reader"><div class="reader-heading"><h2>{t('scanTitle')}</h2><p>{t('readerHint')}</p></div><div class="reader-actions"><button id="screenshot" class="button primary" hidden>{icon('scan')}{t('screenshot')}</button><button id="tab-qr" class="button secondary" hidden>{icon('link')}{t('currentTab')}</button><button id="camera" class="button secondary">{icon('camera')}{t('camera')}</button></div><label class="drop-zone" id="drop-zone" for="file"><span class="upload-icon">{icon('upload')}</span><strong>{t('choose')}</strong><span>{t('drop')}</span><small>{t('imageOnly')}</small></label><input type="file" id="file" accept="image/png,image/jpeg,image/webp" class="sr-only"><div id="camera-view" hidden><video id="camera-video" autoplay muted playsinline></video><button id="stop-camera" class="button secondary">{t('stopCamera')}</button></div><div id="scan-result" hidden><label for="result">{t('result')}</label><textarea id="result" rows="3" readonly></textarea><p class="link-note">{icon('shield')}{t('linkNote')}</p><div class="exports"><button id="copy" class="button secondary">{icon('copy')}{t('copy')}</button><a id="open" class="button primary" target="_blank" rel="noopener noreferrer" hidden>{t('open')}{icon('arrow')}</a><button id="reset-scan" class="button ghost">{t('clear')}</button></div></div><p class="reader-status" id="reader-status" role="status">{t('readyScan')}</p></div></div>
 <div class="tool-bottom">{icon('shield')}{t('noHistory')}<span>QR Scanner · v{v}</span></div></section>'''
def download_link(v,browser,label=None,cls='button secondary'):
 package='firefox' if browser=='firefox' else 'chromium'
 return f'<a class="{cls} pack-download" href="/downloads/qr-scanner-{v}-{package}.zip" download data-browser="{browser}">{icon("download")}{label or t("downloadZip")}</a>'
def home(v,edge):
 browsers=[('chrome','Chrome'),('edge','Edge'),('firefox','Firefox'),('brave','Brave'),('opera','Opera')]
 cards=''.join(f'<article class="browser-card"><span class="browser-monogram browser-{code}"><img src="/assets/browsers/{code}.svg" width="24" height="24" alt=""></span><h3>{name}</h3><small>{"Mozilla · 142+" if code=="firefox" else "Chromium"}</small>{a("edge",edge,"button primary") if code=="edge" else download_link(v,code)}{a("install",f"help.html?browser={code}","browser-guide")}</article>' for code,name in browsers)
 return f'''<main id="main"><section class="hero container"><div><div class="hero-kicker"><span class="live-dot"></span> QR SCANNER <span> / </span> v{v}</div><h1>{t('heroLead')}<br><em>{t('heroAccent')}</em></h1><p>{t('subtitle')}</p><div class="hero-links"><a href="#toolkit" class="button primary">{t('create')}{icon('arrow')}</a><a href="#extension" class="button ghost">{t('navExtension')}{icon('download')}</a></div></div><div class="hero-note"><div class="orbit-mark"><img src="/assets/brand/logo.svg" width="90" height="90" alt=""></div><div><span class="eyebrow">{t('workspace')}</span><p>{t('workspaceDesc')}</p><div class="hero-checks"><span>{icon('check')}{t('free')}</span><span>{icon('check')}{t('local')}</span></div></div></div></section><div class="container workspace-section">{tool(v)}<div class="benefit-strip">{''.join(f'<div>{icon(glyph)}<span><strong>{t(k)}</strong><small>{t(k+"Desc")}</small></span></div>' for glyph,k in [('shield','local'),('download','export'),('qr','noExpiry')])}</div><section id="extension" class="download-section"><div class="section-heading"><div><span class="eyebrow">{t('navExtension')} / v{v}</span><h2>{t('downloadTitle')}</h2><p>{t('downloadDesc')}</p></div><span class="release-chip">{icon('check')}v{v} · {t('latestBadge')}</span></div><div class="browser-grid">{cards}</div><p class="download-note">{t('downloadNote')}</p></section><section class="faq" id="faq"><div><span class="eyebrow">QR SCANNER / FAQ</span><h2>{t('faqTitle')}</h2><p>{t('workspaceDesc')}</p><a href="mailto:qr@haking.tr" class="text-button">qr@haking.tr {icon('arrow')}</a></div><div>{''.join(f'<details><summary>{t("q"+str(i))}{icon("chevron")}</summary><p>{t("a"+str(i))}</p></details>' for i in range(1,5))}</div></section><section class="contact-card"><div>{icon('email')}<h2>{t('contactTitle')}</h2><p>{t('contactDesc')}</p></div><a href="mailto:qr@haking.tr" class="button primary">qr@haking.tr {icon('arrow')}</a></section></div></main>'''
def guide(v):
 buttons=''.join(f'<button type="button" data-guide-browser="{code}" aria-pressed="false">{name}</button>' for code,name in [('chrome','Chrome'),('edge','Edge'),('brave','Brave'),('opera','Opera'),('firefox','Firefox')])
 return f'''<main id="main" class="container guide-page"><div class="page-heading"><span class="eyebrow">QR SCANNER / v{v}</span><h1>{t('helpTitle')}</h1><p>{t('installIntro')}</p></div><div class="guide-layout"><aside class="guide-sidebar"><h2>{t('chooseBrowser')}</h2><div class="browser-picker">{buttons}</div><a id="guide-download" class="button primary pack-download" href="/downloads/qr-scanner-{v}-chromium.zip" data-browser="chrome" download>{icon('download')}{t('downloadAgain')}</a><small>v{v} · ZIP</small><p>{t('downloadNote')}</p></aside><section class="guide-content"><div class="download-success" id="download-success" hidden>{icon('check')}<div><strong>{t('downloadStarted')}</strong><span id="download-name"></span></div></div><div id="chromium-guide"><article class="step-card"><span class="step-number">01</span><div><h2>{t('stepExtract')}</h2><p>{t('step1')}</p><div class="folder-preview">{icon('folder')}<span>QR-Scanner-{v}<small>manifest.json · popup.html · assets</small></span></div></div></article><article class="step-card"><span class="step-number">02</span><div><h2>{t('stepOpen')}</h2><p>{t('step2')}</p><div class="address-copy"><code id="extensions-address">chrome://extensions</code><button type="button" id="copy-address" aria-label="Copy address">{icon('copy')}{t('copyAddress')}</button></div></div></article><article class="step-card"><span class="step-number">03</span><div><h2>{t('stepLoad')}</h2><p>{t('step3')}</p><div class="browser-visual"><div class="browser-visual-header"><span>Extensions</span><span>Developer mode <i></i></span></div><div><span class="mock-load">Load unpacked</span>{icon('arrow')}</div><p>QR-Scanner-{v}/manifest.json</p></div><p>{t('stepReload')}</p></div></article></div><div id="firefox-guide" hidden><article class="step-card"><span class="step-number">01</span><div><h2>{t('stepExtract')}</h2><p>{t('step1')}</p><div class="folder-preview">{icon('folder')}<span>QR-Scanner-{v}<small>manifest.json</small></span></div></article><article class="step-card"><span class="step-number">02</span><div><h2>Firefox 142+</h2><p>{t('firefoxIntro')}</p><div class="address-copy"><code>about:debugging</code></div><p>{t('firefoxStep')}</p></div></article></div><div class="troubleshoot"><h3>{t('troubleshoot')}</h3><p>{t('troubleDesc')}</p><a href="mailto:qr@haking.tr">qr@haking.tr {icon('arrow')}</a></div></section></div></main>'''
def about(v):
 return f'''<main id="main" class="container about-page"><div class="about-hero"><div><span class="eyebrow">QR SCANNER / HAKING</span><h1>{t('aboutTitle')}</h1><p>{t('aboutMission')}</p><a href="./#toolkit" class="button primary">{t('tools')}{icon('arrow')}</a></div><div class="about-symbol"><img src="/assets/brand/logo.svg" width="150" height="150" alt="QR Scanner"><span>QR Scanner</span><small>v{v} · by HaKING</small></div></div><div class="about-story"><span class="eyebrow">{t('navAbout')}</span><p>{t('aboutDesc')}</p></div><div class="about-values">{''.join(f'<article>{icon(glyph)}<h2>{t(k)}</h2><p>{t(desc)}</p></article>' for glyph,k,desc in [('shield','local','privacyDesc'),('qr','free','aboutPrinciples'),('code','aboutOpen','aboutOpenDesc')])}</div><section class="open-source-card"><div><span class="eyebrow">OPEN SOURCE / MIT</span><h2>{t('aboutOpen')}</h2><p>{t('aboutOpenDesc')}</p></div><a href="https://github.com/HaKING06/QR" class="button secondary">GitHub {icon('arrow')}</a></section><section class="contact-card"><div>{icon('email')}<h2>{t('contactTitle')}</h2><p>{t('contactDesc')}</p></div><a href="mailto:qr@haking.tr" class="button primary">qr@haking.tr {icon('arrow')}</a></section></main>'''
def privacy(v):
 return f'<main id="main" class="container privacy-page"><div class="page-heading"><span class="eyebrow">QR SCANNER / v{v}</span><h1>{t("privacyTitle")}</h1><p>2026-11-08</p></div><div class="privacy-content">'+''.join(f'<article>{icon(glyph)}<div><h2>{t(k)}</h2><p>{t(desc)}</p></div></article>' for glyph,k,desc in [('shield','local','privacyDesc'),('qr','noHistory','a2'),('download','latest','downloadNote'),('email','contact','contactDesc')])+'<a href="mailto:qr@haking.tr" class="button primary">qr@haking.tr</a></div></main>'
def popup(v):
 return f'<header class="popup-header"><a class="brand" href="https://qr.haking.tr/" target="_blank" rel="noopener noreferrer"><img src="assets/brand/logo.svg" width="30" height="30" alt=""><span>QR Scanner</span></a><span class="popup-version">v{v}</span>{prefs()}</header><a id="update" class="update-banner" href="https://qr.haking.tr/#extension" target="_blank" rel="noopener noreferrer" hidden>{icon("download")}{t("update")}</a><main id="main">{tool(v,True)}</main><footer class="popup-footer"><a href="https://qr.haking.tr/" target="_blank" rel="noopener noreferrer">qr.haking.tr {icon("arrow")}</a><span>{icon("shield")}{t("local")}</span></footer><p id="status" role="status" aria-live="polite"></p>'
